const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the environment variables
const envVariables = {};
environmentLines = envContent.split('\n');
environmentLines.forEach(line => {
  // Skip empty lines and comments
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=', 2);
    if (key && value) {
      envVariables[key.trim()] = value.trim();
    }
  }
});

// Send POST request
const postData = JSON.stringify(envVariables);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(`Status: ${res.statusCode}`);
  console.log(`Headers: ${JSON.stringify(res.headers)}`);

  res.setEncoding('utf8');
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log(`Response: ${responseData}`);
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

// Write data and end request
req.write(postData);
req.end();
EOF

